/bin/bash -lc "python3 -B - <<'PY'
import subprocess,re

def git(*args): return subprocess.check_output(['git',*args])
def tree(ref):
 return {row.split(b'\\t',1)[1].decode():row.split()[2] for row in git('ls-tree','-r',ref).splitlines()}
for merge in ['dbf9a1e','a711fec','HEAD']:
 parents=git('show','-s','--format=%P',merge).decode().split(); first,incoming=parents
 base=git('merge-base',first,incoming).decode().strip()
 trees=[tree(ref) for ref in [base,first,incoming,merge]]; b,f,i,m=trees
 lost=[p for p in i if i.get(p)"'!=b.get(p) and f.get(p)==b.get(p) and m.get(p)!=i.get(p)]
 print(merge,'"'incoming-only non-preserved paths:',lost)
print('PR-owned paths changed from reviewed baseline:')
base=git('merge-base','f785982','7deb346').decode().strip()
owned=git('diff','--name-only',base,'f785982').decode().splitlines()
for p in owned:
 try: old=git('show','f785982:'+p); new=git('show','HEAD:'+p)
 except subprocess.CalledProcessError: print('MISSING',p); continue
 if old==new: continue
 def strip(s):
  s=re.sub(rb'/\\-.*?\\-/',b'',s,flags=re.S)
  return re.sub(rb'\\s+',b' ',s).strip()
 print('COMMENT-ONLY' if p.endswith('.lean') and strip(old)==strip(new) else 'CHANGED',p)
PY"

